INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'I Remember Grade 7', 'As I look back at my three years in junior high, many happy memories come to my mind. I remember meeting all of you in Grade 7. I was very nervous on my first day. I didn''t know anyone. But soon I made many good friends. I remember our first sports day, when our class won the basketball competition. I also remember the kind teachers who helped me grow. I used to be shy, but now I am much more confident. Time has gone by so quickly. Soon we will graduate and go to different senior high schools. I will always be thankful to my teachers and friends. These three years have been the best of my life.', '记叙文', 118, '[{"q": "How does the writer feel on the first day?", "answer": "D", "options": ["Very happy.", "Very proud.", "Very bored.", "Very nervous."], "explanation": "原文:very nervous on my first day"}, {"q": "What did the writer''s class win?", "answer": "B", "options": ["A writing contest.", "The basketball competition.", "A race.", "A music prize."], "explanation": "原文:won the basketball competition"}, {"q": "How did the writer used to be?", "answer": "B", "options": ["Loud.", "Shy.", "Confident.", "Lazy."], "explanation": "原文:used to be shy"}, {"q": "What will happen soon?", "answer": "A", "options": ["They will graduate.", "They will start Grade 7.", "They will move away.", "They will stop school."], "explanation": "原文:we will graduate"}, {"q": "Who is the writer thankful to?", "answer": "C", "options": ["No one.", "Only parents.", "Teachers and friends.", "Only teachers."], "explanation": "原文:thankful to my teachers and friends"}]'::jsonb, '[{"word": "nervous", "cn": "紧张的"}, {"word": "confident", "cn": "自信的"}, {"word": "thankful", "cn": "感激的"}]'::jsonb, 3, '9', 'U14');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'A Teacher''s Speech', 'Ladies and gentlemen, thank you for coming today to attend the graduation ceremony at No. 3 Junior High School. First of all, I want to congratulate all the students who are here today. I remember meeting all of you when you were just starting Grade 7 three years ago. At that time, you were just children. But now, you have grown into fine young men and women. Although you have all worked very hard over the last three years, your real test is still ahead of you. Soon you will go to senior high school, and the work will be much harder. But I believe you are ready. Remember to keep your cool when things are difficult. Believe in yourselves, and you can overcome any problem. Good luck, and I hope to see you again sometime in the future.', '应用文', 139, '[{"q": "What event is the speech for?", "answer": "D", "options": ["A class party.", "A school trip.", "A sports day.", "A graduation ceremony."], "explanation": "原文:graduation ceremony"}, {"q": "Who is the speaker congratulating?", "answer": "A", "options": ["All the students.", "Only teachers.", "The principal.", "Only parents."], "explanation": "原文:congratulate all the students"}, {"q": "How long ago did the speaker meet the students?", "answer": "B", "options": ["One year ago.", "Three years ago.", "Ten years ago.", "Five years ago."], "explanation": "原文:three years ago"}, {"q": "What is still ahead of the students?", "answer": "A", "options": ["Their real test.", "Their graduation.", "Their holiday.", "Their party."], "explanation": "原文:your real test is still ahead"}, {"q": "What does the speaker tell them to do when things are difficult?", "answer": "C", "options": ["Stay home.", "Give up.", "Keep their cool.", "Run away."], "explanation": "原文:keep your cool when things are difficult"}]'::jsonb, '[{"word": "ceremony", "cn": "典礼;仪式"}, {"word": "congratulate", "cn": "祝贺"}, {"word": "overcome", "cn": "克服;战胜"}]'::jsonb, 3, '9', 'U14');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Changes in Junior High', 'Junior high school is a time of great change. Students change a lot in these three years. When they first arrive in Grade 7, they are young and often shy. By the time they graduate, they have grown taller and become more confident. Their study habits change, too. In Grade 7, many students need help from teachers. By Grade 9, most have learned to study on their own. Students also become more responsible. They learn to keep their cool when faced with problems. They make new friends and learn to work as a team. These three years are not always easy, but they help students grow into better people, ready for the challenges of senior high school.', '说明文', 117, '[{"q": "What is junior high school a time of?", "answer": "B", "options": ["Rest.", "Great change.", "No change.", "Travel."], "explanation": "原文:a time of great change"}, {"q": "How are students when they first arrive in Grade 7?", "answer": "A", "options": ["Young and often shy.", "Old and tired.", "Loud and proud.", "Tall and confident."], "explanation": "原文:young and often shy"}, {"q": "What have most students learned by Grade 9?", "answer": "C", "options": ["To stop learning.", "To skip class.", "To study on their own.", "To depend on teachers."], "explanation": "原文:learned to study on their own"}, {"q": "What do students learn to do when faced with problems?", "answer": "D", "options": ["Run away.", "Give up.", "Cry.", "Keep their cool."], "explanation": "原文:keep their cool when faced with problems"}, {"q": "What are students ready for after three years?", "answer": "D", "options": ["Going home.", "Stopping school.", "Staying in Grade 7.", "The challenges of senior high."], "explanation": "原文:ready for the challenges of senior high"}]'::jsonb, '[{"word": "graduate", "cn": "毕业"}, {"word": "responsible", "cn": "有责任心的"}, {"word": "confident", "cn": "自信的"}]'::jsonb, 3, '9', 'U14');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Looking to the Future', 'Now that junior high is almost over, it is time to look to the future. Many students feel both excited and a little worried about senior high school. The work will be harder, and there will be new challenges. But change is a part of growing up. There are some things you can do to get ready. First, set clear goals. Think about what you want to achieve. Second, work hard, but also keep your cool when things get difficult. Third, believe in yourself. If you believe you can do it, you are already halfway there. Remember, every new beginning is a chance to grow. So spread your wings and fly. The future is full of hope, and it belongs to you.', '议论文', 122, '[{"q": "How do many students feel about senior high?", "answer": "A", "options": ["Both excited and worried.", "Nothing at all.", "Only bored.", "Only sad."], "explanation": "原文:both excited and a little worried"}, {"q": "What is the first thing you can do to get ready?", "answer": "B", "options": ["Stop working.", "Set clear goals.", "Stay home.", "Forget the past."], "explanation": "原文:First, set clear goals"}, {"q": "What should you do when things get difficult?", "answer": "C", "options": ["Run away.", "Give up.", "Keep your cool.", "Cry."], "explanation": "原文:keep your cool when things get difficult"}, {"q": "What does the writer say about believing in yourself?", "answer": "B", "options": ["It is useless.", "You are already halfway there.", "It is hard.", "It is wrong."], "explanation": "原文:already halfway there"}, {"q": "Who does the future belong to?", "answer": "D", "options": ["Teachers.", "Parents.", "No one.", "You."], "explanation": "原文:it belongs to you"}]'::jsonb, '[{"word": "wing", "cn": "翅膀"}, {"word": "believe", "cn": "相信"}, {"word": "future", "cn": "未来"}]'::jsonb, 3, '9', 'U14');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'My Plans for the Future', 'My name is Lily, and I am about to graduate from junior high school. When I look back, I remember being a quiet girl in Grade 7. Now I have many friends and big dreams. So what are my plans for the future? First, I am going to work hard in senior high school. I want to get good grades so that I can go to a good university. After that, I am going to study science. I have always been thirsty for knowledge. In ten years, I hope I will be a doctor. I want to help sick people and make the world a better place. I know the road ahead will not be easy. But I believe that if I keep trying, I will reach my goals one day.', '记叙文', 131, '[{"q": "What is Lily about to do?", "answer": "B", "options": ["Stop school.", "Graduate from junior high school.", "Start Grade 7.", "Move away."], "explanation": "原文:about to graduate from junior high"}, {"q": "How was Lily in Grade 7?", "answer": "A", "options": ["A quiet girl.", "A lazy girl.", "A new teacher.", "A loud girl."], "explanation": "原文:a quiet girl in Grade 7"}, {"q": "What is Lily going to study?", "answer": "C", "options": ["History.", "Music.", "Science.", "Art."], "explanation": "原文:going to study science"}, {"q": "What does Lily hope to be in ten years?", "answer": "D", "options": ["A singer.", "A teacher.", "A manager.", "A doctor."], "explanation": "原文:I will be a doctor"}, {"q": "What does Lily believe?", "answer": "A", "options": ["If she keeps trying, she will reach her goals.", "She will fail.", "The road is easy.", "She should give up."], "explanation": "原文:if I keep trying, I will reach my goals"}]'::jsonb, '[{"word": "graduate", "cn": "毕业"}, {"word": "thirsty", "cn": "渴望的"}, {"word": "ahead", "cn": "在前面"}]'::jsonb, 3, '9', 'U14');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Graduation Ceremony Notice', 'GRADUATION CEREMONY — CLASS OF GRADE 9! Dear students, our graduation ceremony is coming soon. Here are the details. DATE: Friday, June 28th. TIME: 9:00 a.m. to 11:00 a.m. PLACE: The school hall. WHAT TO WEAR: Please wear your school uniform. THE PROGRAM: First, our head teacher will give a speech. Then, we will give out the graduation certificates. After that, a few students will share their memories of these three years. Lastly, we will take a class photo together. This is an important day. It is a time to look back at our happy memories and look ahead to a bright future. We hope to see all of you there. Let''s celebrate this special moment together!', '应用文', 117, '[{"q": "When is the graduation ceremony?", "answer": "B", "options": ["Monday, June 1st.", "Friday, June 28th.", "Friday, May 28th.", "Sunday, July 5th."], "explanation": "原文:Friday, June 28th"}, {"q": "Where will the ceremony be held?", "answer": "C", "options": ["The gym.", "The library.", "The school hall.", "The playground."], "explanation": "原文:The school hall"}, {"q": "What should students wear?", "answer": "C", "options": ["A suit.", "Costumes.", "Their school uniform.", "Sports clothes."], "explanation": "原文:wear your school uniform"}, {"q": "What will happen first in the program?", "answer": "A", "options": ["The head teacher will give a speech.", "Students share memories.", "Certificates given.", "A class photo."], "explanation": "原文:First, our head teacher will give a speech"}, {"q": "What will they do lastly?", "answer": "D", "options": ["Leave early.", "Hand out food.", "Give a speech.", "Take a class photo."], "explanation": "原文:Lastly, we will take a class photo"}]'::jsonb, '[{"word": "graduation", "cn": "毕业"}, {"word": "ceremony", "cn": "典礼"}, {"word": "lastly", "cn": "最后"}]'::jsonb, 3, '9', 'U14');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U14', 'Looking Back', 'As I look (1)____ at my three years in junior high, many happy memories come to my (2)____. I remember (3)____ all of you in Grade 7. I was very (4)____ on my first day. But soon I made many good (5)____. I remember our first sports day, when our class (6)____ the basketball competition. I used to (7)____ shy, but now I am much more (8)____. Time has gone by so (9)____. Soon we will (10)____ and go to senior high. These three years have been the best of my life.', 92, 3, '[{"q": "1", "answer": "A", "options": ["back", "color", "game", "price"], "explanation": "look back 回顾"}, {"q": "2", "answer": "D", "options": ["color", "game", "price", "mind"], "explanation": "心头 come to mind"}, {"q": "3", "answer": "A", "options": ["meeting", "meets", "met", "to meet"], "explanation": "remember doing 遇见"}, {"q": "4", "answer": "D", "options": ["happy", "glad", "proud", "nervous"], "explanation": "紧张 nervous"}, {"q": "5", "answer": "B", "options": ["games", "friends", "prices", "colors"], "explanation": "朋友 friends"}, {"q": "6", "answer": "B", "options": ["wins", "won", "win", "winning"], "explanation": "赢 won"}, {"q": "7", "answer": "A", "options": ["be", "been", "being", "was"], "explanation": "used to be 过去是"}, {"q": "8", "answer": "B", "options": ["sad", "confident", "tired", "shy"], "explanation": "自信 confident"}, {"q": "9", "answer": "C", "options": ["late", "slow", "quickly", "hard"], "explanation": "快 quickly"}, {"q": "10", "answer": "C", "options": ["lose", "break", "graduate", "build"], "explanation": "毕业 graduate"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U14', 'The Teacher''s Words', 'Ladies and (1)____, welcome to our graduation (2)____. First of all, I want to (3)____ all the students here. I remember (4)____ you in Grade 7. At that time, you were just (5)____. But now you have grown (6)____ fine young people. You have all worked very (7)____. But your real test is still (8)____ of you. Soon the work will be much (9)____. Remember to keep your (10)____ when things are difficult. Believe in yourselves, and you can overcome any problem.', 82, 3, '[{"q": "1", "answer": "C", "options": ["games", "colors", "gentlemen", "prices"], "explanation": "先生们 gentlemen"}, {"q": "2", "answer": "B", "options": ["price", "ceremony", "color", "game"], "explanation": "典礼 ceremony"}, {"q": "3", "answer": "A", "options": ["congratulate", "lose", "break", "build"], "explanation": "祝贺 congratulate"}, {"q": "4", "answer": "D", "options": ["to meet", "met", "meets", "meeting"], "explanation": "remember doing 遇见"}, {"q": "5", "answer": "C", "options": ["colors", "games", "children", "prices"], "explanation": "孩子 children"}, {"q": "6", "answer": "A", "options": ["into", "on", "off", "in"], "explanation": "grow into 成长为"}, {"q": "7", "answer": "B", "options": ["easy", "hard", "slow", "late"], "explanation": "努力 hard"}, {"q": "8", "answer": "D", "options": ["game", "price", "color", "ahead"], "explanation": "ahead of 在前面"}, {"q": "9", "answer": "B", "options": ["later", "harder", "slower", "easier"], "explanation": "更难 harder"}, {"q": "10", "answer": "A", "options": ["cool", "price", "color", "game"], "explanation": "keep cool 冷静"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U14', 'Changes', 'Junior high school is a time of great (1)____. Students change a lot in these three (2)____. When they first arrive in Grade 7, they are young and often (3)____. By the time they (4)____, they have grown taller and become more (5)____. Their study habits change, too. By Grade 9, most have (6)____ to study on their own. Students also become more (7)____. They learn to keep their cool when faced with (8)____. These three years are not always (9)____, but they help students (10)____ into better people.', 89, 3, '[{"q": "1", "answer": "A", "options": ["change", "price", "game", "color"], "explanation": "变化 change"}, {"q": "2", "answer": "C", "options": ["games", "prices", "years", "colors"], "explanation": "年 years"}, {"q": "3", "answer": "D", "options": ["confident", "loud", "old", "shy"], "explanation": "害羞 shy"}, {"q": "4", "answer": "D", "options": ["lose", "break", "build", "graduate"], "explanation": "毕业 graduate"}, {"q": "5", "answer": "B", "options": ["shy", "confident", "tired", "sad"], "explanation": "自信 confident"}, {"q": "6", "answer": "C", "options": ["break", "build", "learned", "lose"], "explanation": "学会 learned"}, {"q": "7", "answer": "A", "options": ["responsible", "sad", "quiet", "lazy"], "explanation": "有责任心 responsible"}, {"q": "8", "answer": "A", "options": ["problems", "games", "prices", "colors"], "explanation": "问题 problems"}, {"q": "9", "answer": "B", "options": ["hard", "easy", "cold", "old"], "explanation": "容易 easy"}, {"q": "10", "answer": "B", "options": ["break", "grow", "build", "lose"], "explanation": "成长 grow"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U14', 'Looking Ahead', 'Now that junior high is almost (1)____, it is time to look to the (2)____. Many students feel both excited and a little (3)____ about senior high. The work will be (4)____, and there will be new (5)____. But change is a part of growing (6)____. First, set clear (7)____. Think about what you want to achieve. Second, work hard, but keep your (8)____. Third, believe in (9)____. Remember, every new beginning is a chance to grow. So spread your (10)____ and fly. The future belongs to you.', 88, 3, '[{"q": "1", "answer": "A", "options": ["over", "up", "in", "on"], "explanation": "结束 over"}, {"q": "2", "answer": "D", "options": ["price", "game", "color", "future"], "explanation": "未来 future"}, {"q": "3", "answer": "B", "options": ["glad", "worried", "proud", "happy"], "explanation": "担心 worried"}, {"q": "4", "answer": "B", "options": ["easier", "harder", "later", "slower"], "explanation": "更难 harder"}, {"q": "5", "answer": "A", "options": ["challenges", "prices", "games", "colors"], "explanation": "挑战 challenges"}, {"q": "6", "answer": "A", "options": ["up", "off", "on", "in"], "explanation": "grow up 长大"}, {"q": "7", "answer": "C", "options": ["prices", "colors", "goals", "games"], "explanation": "目标 goals"}, {"q": "8", "answer": "B", "options": ["price", "cool", "color", "game"], "explanation": "冷静 cool"}, {"q": "9", "answer": "C", "options": ["game", "price", "yourself", "color"], "explanation": "自己 yourself"}, {"q": "10", "answer": "D", "options": ["games", "colors", "prices", "wings"], "explanation": "翅膀 wings"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U14', 'Lily''s Plans', 'My name is Lily, and I am about to (1)____ from junior high. When I look back, I remember (2)____ a quiet girl in Grade 7. Now I have big (3)____. So what are my plans for the (4)____? First, I am going to (5)____ hard in senior high. I want good grades so I can go to a good (6)____. After that, I am going to study (7)____. I have always been (8)____ for knowledge. In ten years, I hope I (9)____ be a doctor. I know the road ahead will not be (10)____. But if I keep trying, I will reach my goals.', 105, 3, '[{"q": "1", "answer": "C", "options": ["break", "lose", "graduate", "build"], "explanation": "毕业 graduate"}, {"q": "2", "answer": "B", "options": ["been", "being", "to be", "was"], "explanation": "remember doing 是"}, {"q": "3", "answer": "A", "options": ["dreams", "colors", "prices", "games"], "explanation": "梦想 dreams"}, {"q": "4", "answer": "A", "options": ["future", "color", "game", "price"], "explanation": "未来 future"}, {"q": "5", "answer": "A", "options": ["work", "break", "build", "lose"], "explanation": "努力 work"}, {"q": "6", "answer": "D", "options": ["game", "price", "color", "university"], "explanation": "大学 university"}, {"q": "7", "answer": "B", "options": ["game", "science", "price", "color"], "explanation": "科学 science"}, {"q": "8", "answer": "C", "options": ["glad", "proud", "thirsty", "happy"], "explanation": "渴望 thirsty"}, {"q": "9", "answer": "B", "options": ["am", "will", "have", "did"], "explanation": "将来 will be"}, {"q": "10", "answer": "D", "options": ["old", "hard", "cold", "easy"], "explanation": "容易 easy"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U14', 'Graduation Day', 'Our graduation (1)____ is coming soon. It will be on Friday, June 28th, in the school (2)____. Please wear your school (3)____. First, our head teacher will give a (4)____. Then, we will give out the graduation (5)____. After that, a few students will (6)____ their memories of these three years. (7)____, we will take a class (8)____ together. This is an important (9)____. It is a time to look back at our happy memories and look (10)____ to a bright future. Let''s celebrate this special moment together!', 88, 3, '[{"q": "1", "answer": "B", "options": ["price", "ceremony", "game", "color"], "explanation": "典礼 ceremony"}, {"q": "2", "answer": "A", "options": ["hall", "game", "color", "price"], "explanation": "礼堂 hall"}, {"q": "3", "answer": "C", "options": ["game", "price", "uniform", "color"], "explanation": "校服 uniform"}, {"q": "4", "answer": "A", "options": ["speech", "price", "game", "color"], "explanation": "演讲 speech"}, {"q": "5", "answer": "D", "options": ["games", "colors", "prices", "certificates"], "explanation": "证书 certificates"}, {"q": "6", "answer": "D", "options": ["lose", "build", "break", "share"], "explanation": "分享 share"}, {"q": "7", "answer": "B", "options": ["First", "Lastly", "Once", "Never"], "explanation": "最后 lastly"}, {"q": "8", "answer": "C", "options": ["price", "game", "photo", "color"], "explanation": "照片 photo"}, {"q": "9", "answer": "B", "options": ["price", "day", "color", "game"], "explanation": "日子 day"}, {"q": "10", "answer": "A", "options": ["ahead", "away", "back", "down"], "explanation": "look ahead 展望"}]'::jsonb, 6);
