INSERT INTO public.junior_writing_prompts (id, grade, topic, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, difficulty, title_en, high_sentences, error_pairs, paragraph_template, volume, unit) SELECT gen_random_uuid(), 9, 'Looking Back and Looking Ahead', '写一篇短文,回顾你的初中生活(用remember doing/used to/现在完成时),并展望高中或未来(用will/be going to)。60词左右。', 'Write a short passage on the topic: "Looking Back and Looking Ahead".', '["回顾初中难忘的事(I remember.../I used to...)", "你这三年的变化(I have become...)", "对高中或未来的计划(I will.../I''m going to...)", "你的感受或愿望"]'::jsonb, 70, 100, 'As I look back at my three years in junior high, I have many happy memories. I remember meeting all my classmates in Grade 7. I used to be very shy, but now I have become much more confident. I have also made many good friends. Soon I will graduate and start senior high school. Things will be different, and the work will be harder. But I''m going to study hard and follow my dreams. I will always be thankful to my teachers and friends.', 'content:含初中回顾/个人变化/未来计划/感受(4分)；language:正确使用remember doing/used to/will/现在完成时(3分)；structure:叙事清楚、衔接得当(2分)；wordcount:词数达标、书写规范(1分)', 3, 'Looking Back and Looking Ahead', '["I remember meeting ...", "I used to ..., but now ...", "I have become much better at ...", "Things will be different ...", "I''m going to ...", "I will always be thankful to ..."]'::jsonb, '[]'::jsonb, '要点:回顾初中难忘的事(I remember.../I used to...)；你这三年的变化(I have become...)；对高中或未来的计划(I will.../I''m going to...)；你的感受或愿望', '9', 'U14' WHERE NOT EXISTS (SELECT 1 FROM public.junior_writing_prompts WHERE volume='9' AND unit='U14' AND topic='Looking Back and Looking Ahead');
