UNION ALL SELECT 'reading', count(*), 6 FROM public.junior_reading WHERE volume='9' AND unit='U14'
UNION ALL SELECT 'cloze', count(*), 6 FROM public.junior_cloze WHERE volume='9' AND unit='U14'
UNION ALL SELECT 'listening', count(*), 6 FROM public.junior_listening_exercises WHERE volume='9' AND unit='U14'
UNION ALL SELECT 'writing', count(*), 1 FROM public.junior_writing_prompts WHERE volume='9' AND unit='U14';